package com.techconsulting.lending.domain;
import jakarta.persistence.*; import lombok.Getter; import lombok.Setter; import java.math.BigDecimal; import java.time.*;
@Entity @Table(name="manual_lending",uniqueConstraints=@UniqueConstraint(columnNames={"user_id","scheme_id"})) @Getter @Setter
public class ManualLending { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="user_id") private Long userId; @Column(name="scheme_id") private String schemeId; @Column(name="loan_id") private String loanId; @Column(name="borrower_name") private String borrowerName; @Column(name="invested_amount") private BigDecimal investedAmount; @Column(name="tenure_months") private int tenureMonths; @Column(name="principal_emi") private BigDecimal principalEmi; @Column(name="amount_received") private BigDecimal amountReceived; @Column(name="calculated_principal_received") private BigDecimal calculatedPrincipalReceived; @Column(name="calculated_interest_received") private BigDecimal calculatedInterestReceived; @Column(name="market_value") private BigDecimal marketValue; @Column(name="return_amount") private BigDecimal returnAmount; @Column(name="return_percentage") private BigDecimal returnPercentage; @Column(name="outstanding_principal") private BigDecimal outstandingPrincipal; @Column(name="npa_amount") private BigDecimal npaAmount; @Column(name="investment_date") private LocalDate investmentDate; @Column(name="last_emi_paid_on") private LocalDate lastEmiPaidOn; @Column(name="expected_maturity_date") private LocalDate expectedMaturityDate; @Column(name="loan_status") private String loanStatus; @Column(name="investment_status") private String investmentStatus; private int dpd; @Column(name="is_npa") private boolean npa; @Column(name="npa_reason") private String npaReason; @Column(columnDefinition="text") private String comments; @Column(name="source_import_batch_id") private Long sourceImportBatchId; @Version private long version; }
